from pathlib import Path
import json, html, hashlib, re, posixpath, sys
R=Path(__file__).resolve().parents[1]; S=Path(sys.argv[1]) if len(sys.argv)>1 else R/'site'; B='learn/hindi/studio'; E=lambda x:html.escape(str(x),quote=True)
BOOKS=[('kids','बाल हिंदी','Kids','अ'),('beginner','प्रारंभिक हिंदी','Beginner','क'),('intermediate','मध्यम हिंदी','Intermediate','श'),('advanced','उन्नत हिंदी','Advanced','ज्ञ'),('mastery','संपूर्ण हिंदी','Mastery','हिं'),('adult','जीवन की हिंदी','Adults & seniors','जी')]
entries=[]; cards={}; books=[]; phases=[]; counts={'chapters':0,'lessons':0,'worksheets':0,'assessments':0}; sections=[]; ids=set()
def route(path):
 path=path.strip('/')+'/'
 if not (S/path/'index.html').is_file():raise ValueError('Missing '+path)
 return posixpath.relpath(path,B)+'/'
def entry(book,label,hi,en,path,kind,keywords='',id=None):
 entries.append(dict(book=book,label=label,hi=hi,en=en,path=route(path),type=kind,keywords=keywords,id=id));return entries[-1]
def card(book,hi,en,path):
 key=hashlib.sha256((book+'\0'+hi+'\0'+en).encode()).hexdigest()[:24];cards.setdefault(key,dict(id=key,book=book,hi=hi,en=en,path=route(path)))
for bid,hi,en,g in BOOKS:
 d=json.loads((S/f'data/learning/hindi-{bid}-book.json').read_text()); root=d['root']; storage='adult-hi' if bid=='adult' else bid; book=dict(id=bid,hi=hi,en=en,g=g,path=route(root),ids=[],storage=storage);books.append(book)
 for p in d.get('phases',d.get('stages',[])):
  group=[]
  for c in p['chapters']:
   path=c['path'];group.append(entry(bid,hi,c['hi'],c['en'],path,'chapter'));counts['chapters']+=1
   if bid=='adult':
    ls=[dict(hi=c['hi']+' — '+h,en=c['en']+' — '+e,path=path+f'lesson-{j:02}/',id=f'adult-{c["n"]:02}-{j:02}',words=[(x[0],x[2]) for x in (c['phrases'] if j==1 else c['dialogue'])],aliases=' '.join(x[1] for x in (c['phrases'] if j==1 else c['dialogue']))) for j,h,e in [(1,'भाषा','Language'),(2,'संवाद','Conversation')]]
   else:ls=c['lessons']
   for l in ls:
    if l['id'] in ids:raise ValueError('Duplicate lesson id '+l['id'])
    ids.add(l['id']);book['ids'].append(l['id']);group.append(entry(bid,hi,l['hi'],l['en'],l['path'],'lesson',c['hi']+' '+c['en']+' '+l.get('aliases','')+' '+' '.join(' '.join(w) for w in l['words']),l['id']));counts['lessons']+=1
    for w,m in l['words']:card(bid,w,m,l['path'])
   group.append(entry(bid,hi,c['hi']+' — कार्यपत्रक',c['en']+' worksheet',path+'worksheet/','worksheet'));counts['worksheets']+=1
  if bid=='adult':group.append(entry(bid,hi,p['hi']+' — स्वमूल्यांकन',p['en']+' assessment',root+'/'+p['id']+'/assessment/','assessment'));counts['assessments']+=1
  sections.append((hi+' · '+p['hi'],group))
# Deduplicated vocabulary within each book, intentional repetition across books retained.
D=dict(version=1,books=books,entries=entries,cards=list(cards.values()),counts=counts)
(S/'data/learning/hindi-unified-index.json').write_text(json.dumps(D,ensure_ascii=False,separators=(',',':')))
options='<option value="all">All textbooks</option>'+''.join(f'<option value="{b["id"]}">{E(b["hi"])} · {E(b["en"])}</option>' for b in books)
course=''.join(f'<article class="course" data-book="{b["id"]}"><div class="glyph">{b["g"]}</div><div><h3><a href="{b["path"]}">{b["hi"]} ↗</a></h3><small>{b["en"]}</small><progress max="{len(b["ids"])}" value="0" aria-label="{b["en"]} progress"></progress><div class="rowend"><small data-count>0 / {len(b["ids"])}</small><a data-resume hidden>Resume →</a></div></div></article>' for b in books)
static=''.join(f'<details><summary>{E(title)} · {len(g)} resources</summary><ul>'+''.join(f'<li><a href="{E(x["path"])}">{E(x["hi"])}</a> <small>{E(x["type"])}</small></li>' for x in g)+'</ul></details>' for title,g in sections)
art='''<svg viewBox="0 0 320 240" aria-hidden="true"><circle cx="160" cy="120" r="100" fill="#245c45"/><g class="orbit" fill="none" stroke="#d7b66b" stroke-dasharray="2 8"><ellipse cx="160" cy="120" rx="148" ry="90" transform="rotate(-23 160 120)"/><circle cx="160" cy="120" r="114"/></g><g class="glow"><path d="M38 77Q100 52 160 91Q220 52 282 77L290 182Q225 161 160 200Q95 161 30 182Z" fill="#b27a42"/><path d="M43 65Q105 43 160 86V190Q103 153 37 172Z" fill="#fff2ce"/><path d="M277 65Q215 43 160 86V190Q217 153 283 172Z" fill="#e9d4a6"/><g stroke="#a98e57" stroke-width="2" fill="none"><path d="M55 116Q107 99 146 127M53 133Q105 116 146 144M53 150Q105 133 146 161M174 127Q215 99 265 116M174 144Q215 116 267 133M174 161Q215 133 267 150"/></g><text x="97" y="100" fill="#245c45" font-size="36" text-anchor="middle">अ आ</text><text x="225" y="100" fill="#245c45" font-size="36" text-anchor="middle">क ख</text></g><text x="30" y="45" fill="#f0d79d" font-size="20">ज्ञ</text><text x="268" y="42" fill="#f0d79d" font-size="22">✧</text></svg>'''
body=f'''<a class="skip" href="#main">Skip to content</a><header class="top"><nav><a class="brand" href="../"><i>ए</i>EkGuru</a><a href="../">Hindi</a><a href="#library">Library</a><a href="#practice">Practice</a><span class="spacer"></span><button id="large" aria-pressed="false" type="button">A+</button><button id="theme" aria-pressed="false" type="button">◐ Theme</button></nav></header><main class="wrap" id="main"><div class="crumb">Learn / Hindi / Study Studio</div><section class="hero"><div><span class="eyebrow">EKGURU · HINDI STUDY STUDIO</span><h1>अभ्यास से <em>अभिव्यक्ति।</em></h1><p>One place to find, read, revise and practise every textbook.</p><a class="action" href="#practice">अभ्यास शुरू करें →</a></div>{art}</section><div class="stats"><div class="stat"><b>{len(books)}</b><small>Textbooks</small></div><div class="stat"><b>{counts['lessons']}</b><small>Lessons</small></div><div class="stat"><b>{counts['worksheets']}</b><small>Worksheets</small></div><div class="stat"><b id="total-done">0 / {counts['lessons']}</b><small>Completed on this device</small></div></div><div class="head"><div><span class="badge">01 / YOUR BOOKS</span><h2>मेरी पढ़ाई</h2></div><small>Self-marked progress, not certification</small></div><div class="course-grid">{course}</div><div class="head" id="practice"><div><span class="badge">02 / PRACTICE</span><h2>पुनरावृत्ति और श्रुतलेख</h2></div><label>Practice deck <select id="practice-book">{options}</select></label></div><div class="tools"><section class="panel"><h3>याद करें · Flashcards</h3><small id="due">{len(cards)} cards</small><div class="flash"><div><b id="face" lang="hi">नमस्ते</b><p id="meaning" hidden></p></div></div><div class="controls"><button id="reveal" class="action">Show meaning</button><button id="listen">Listen</button><button id="skip-card">Skip</button></div><div class="controls"><button data-rate="0" disabled>Again</button><button data-rate="1" disabled>Remembered</button><a id="source" hidden>Open source lesson ↗</a></div><p id="flash-status" class="feedback" role="status"></p></section><section class="panel"><h3>सुनकर लिखें · Dictation</h3><p>Listen to a word or phrase from your selected textbook, then type it in Hindi.</p><div class="controls"><button id="dict-listen" class="action">Listen slowly</button><button id="dict-next">New item</button></div><label for="dict-input">अपना उत्तर</label><div class="controls"><input id="dict-input" lang="hi" autocomplete="off" placeholder="यहाँ लिखें"></div><div class="controls"><button id="dict-check">Check exact text</button><button id="dict-reveal">Reveal</button></div><p id="dict-status" class="feedback" role="status"></p><p id="dict-answer" hidden></p></section></div><p class="notice">Audio uses the device Hindi voice when available. Reviews are self-rated. No pronunciation grading or native recording is implied.</p><div class="head" id="library"><div><span class="badge">03 / LIBRARY</span><h2>पाठ, अध्याय और कार्यपत्रक</h2></div><small>{len(entries)} indexed resources</small></div><div class="filter"><input type="search" id="search" aria-label="Search textbooks" placeholder="संधि, grammar, travel…"><select id="search-book" aria-label="Textbook">{options}</select><select id="search-type" aria-label="Resource type"><option value="all">All resources</option><option value="lesson">Lessons</option><option value="chapter">Chapters</option><option value="worksheet">Worksheets</option><option value="assessment">Assessments</option><option value="saved">Bookmarks</option></select></div><p id="result-count" class="muted" aria-live="polite"></p><div class="results" id="results"></div><div class="controls"><button id="more">Show more</button></div><div class="directory"><details><summary>Full textbook directory (works without JavaScript)</summary>{static}</details></div><div class="head"><h2>Local study backup</h2></div><section class="panel"><p>Export or restore Studio bookmarks, flashcard review dates and display settings. Existing textbook progress and writing drafts are not included or changed.</p><div class="controls"><button id="export">Export JSON</button><label>Restore Studio JSON <input id="import" type="file" accept="application/json,.json"></label></div><p id="backup-status" role="status"></p><p class="notice" id="storage-note">Data stays in this browser; no account required.</p></section><noscript><p>JavaScript is needed for the interactive tools. All textbooks and the full directory remain accessible.</p></noscript><p class="notice">Draft educational material pending native-speaker review. Class ranges are curriculum inspiration, not school qualifications. New pages remain noindex.</p></main><footer>EkGuru · Hindi study tools</footer>'''
jsondata=json.dumps(D,ensure_ascii=False,separators=(',',':')).replace('<','\\u003c')
page='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="robots" content="noindex, follow"><link rel="canonical" href="https://ekguru.shop/learn/hindi/studio/"><title>Hindi Study Studio — Practice & Textbook Library | EkGuru</title><meta name="description" content="Find Hindi textbooks, lessons, worksheets and practise vocabulary and dictation on EkGuru."><link rel="stylesheet" href="../../../css/hindi-study-studio.css"></head><body>'+body+'<script type="application/json" id="studio-data">'+jsondata+'</script><script src="../../../js/hindi-study-studio.js" defer></script></body></html>'
(S/B).mkdir(parents=True,exist_ok=True);(S/B/'index.html').write_text(page)
(S/'css/hindi-study-studio.css').write_text((R/'source/studio.css').read_text());(S/'js/hindi-study-studio.js').write_text((R/'source/studio.js').read_text())
# Keep old reader code intact. Add a common navigation strip (no script dependency), cross-book progression.
for b in books:
 root=S/'learn/hindi'/('older-adults' if b['id']=='adult' else b['id']);
 for f in root.rglob('index.html'):
  h=f.read_text();cur=f.parent.relative_to(S).as_posix();url=posixpath.relpath(B,cur)+'/'; nav=f'<nav aria-label="Shared Hindi study tools" class="eg-studio-nav"><a href="{url}">Study Studio · अभ्यास</a> <span>·</span> <a href="{url}#library">All lessons</a> <span>·</span> <a href="{url}#practice">Revision</a></nav>'
  if 'class="eg-studio-nav"' not in h:
   h=re.sub(r'(<main\b[^>]*>)',lambda m:m[0]+nav,h,count=1);h=h.replace('</head>','<link rel="stylesheet" href="'+posixpath.relpath('css/hindi-shared-reader.css',cur)+'"></head>',1)
  h=h.replace('href="https://ekguru.shop/learn/hindi/"','href="'+posixpath.relpath('learn/hindi',cur)+'/"')
  f.write_text(h)
for i,b in enumerate(books[:4]):
 last=next(x for x in reversed(entries) if x['book']==b['id'] and x['type']=='lesson'); f=(S/B/last['path']/'index.html').resolve(); h=f.read_text(); dest=posixpath.relpath('learn/hindi/'+books[i+1]['id'],f.parent.relative_to(S).as_posix())+'/';
 if 'class="eg-next-book"' not in h:h=h.replace('</main>',f'<aside class="eg-next-book"><a href="{dest}">अगली किताब · {books[i+1]["hi"]} →</a></aside></main>',1)
 f.write_text(h)
(S/'css/hindi-shared-reader.css').write_text('.eg-studio-nav{display:flex;flex-wrap:wrap;gap:10px;align-items:center;font-size:.85rem;margin:8px 0 15px}.eg-studio-nav a,.eg-next-book a{color:inherit;text-decoration:underline;text-underline-offset:3px}.eg-next-book{padding:16px;margin:20px 0;border:1px solid currentColor;border-radius:14px;font-weight:700}@media print{.eg-studio-nav,.eg-next-book{display:none!important}}')
# Local preview home only, never install over existing hub.
preview='<h1>हिंदी की पाठ्यपुस्तकें</h1><p>Combined offline preview · all six draft textbooks</p><div class="course-grid">'+''.join(f'<article class="course"><div class="glyph">{b["g"]}</div><div><h2><a href="{("older-adults" if b["id"]=="adult" else b["id"])}/">{b["hi"]}</a></h2><small>{b["en"]} · 40 chapters</small></div></article>' for b in books)+'</div><p><a class="action" href="studio/">Open Study Studio →</a></p>'
(S/'learn/hindi/index.html').write_text('<!doctype html><html lang="hi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Hindi — Combined offline preview</title><link rel="stylesheet" href="../../css/hindi-study-studio.css"></head><body><main class="wrap">'+preview+'</main></body></html>')
(R/'preview.html').write_text(page.replace('<link rel="stylesheet" href="../../../css/hindi-study-studio.css">','<style>'+(R/'source/studio.css').read_text()+'</style>').replace('<script src="../../../js/hindi-study-studio.js" defer></script>','<script>'+(R/'source/studio.js').read_text()+'</script>').replace('<main class="wrap" id="main">','<main class="wrap" id="main"><p class="notice">Standalone preview: course navigation requires the extracted ZIP and local server.</p>'))
print(json.dumps(dict(counts=counts,entries=len(entries),cards=len(cards),books=len(books)),ensure_ascii=False))
